package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.nbt.*;import net.minecraft.server.level.ServerLevel;import net.minecraft.world.level.saveddata.SavedData;import net.minecraft.core.SectionPos;import net.minecraft.world.phys.*;import java.util.*;
public final class NtStore extends SavedData {
 public final Map<UUID,NtTunnel> tunnels=new LinkedHashMap<>();private final Map<Long,List<Face>> cells=new HashMap<>();public final Map<UUID,Undo> undo=new HashMap<>();private long revision;private final List<CompoundTag> quarantined=new ArrayList<>();private final Map<UUID,Integer> counts=new HashMap<>();private final Map<UUID,AABB> bounds=new HashMap<>();
 public record Undo(UUID id,long expected,NtTunnel before){}
 public record Face(UUID tunnel,NtGeometry.Triangle triangle,AABB bounds){}
 public record Hit(Face face,double time){}
 public static NtStore get(ServerLevel l){return l.getDataStorage().computeIfAbsent(NtStore::load,NtStore::new,"sbw_nt01_tunnels");}
 public long next(){return ++revision;}
 private static NtStore load(CompoundTag n){NtStore s=new NtStore();s.revision=n.getLong("revision");var list=n.getList("tunnels",10);for(int i=0;i<Math.min(128,list.size());i++)try{NtTunnel t=NtTunnel.load(list.getCompound(i));if(!t.plan().valid())throw new IllegalArgumentException("Saved plan invalid");s.put(t);s.revision=Math.max(s.revision,t.revision());}catch(IllegalArgumentException e){s.quarantined.add(list.getCompound(i).copy());SbwDroneRangeConfig.LOGGER.error("NT-01 record could not be indexed; preserving its original NBT for recovery: {}",e.getMessage());}var undos=n.getList("undo",10);for(int i=0;i<Math.min(128,undos.size());i++)try{var a=undos.getCompound(i);s.undo.put(a.getUUID("player"),new Undo(a.getUUID("id"),a.getLong("expected"),a.contains("before",10)?NtTunnel.load(a.getCompound("before")):null));}catch(IllegalArgumentException ignored){}return s;}
 @Override public CompoundTag save(CompoundTag n){n.putLong("revision",revision);ListTag list=new ListTag(),undos=new ListTag();for(NtTunnel t:tunnels.values())list.add(t.save());for(var raw:quarantined)list.add(raw.copy());n.put("tunnels",list);for(var e:undo.entrySet()){var a=new CompoundTag();a.putUUID("player",e.getKey());a.putUUID("id",e.getValue().id);a.putLong("expected",e.getValue().expected);if(e.getValue().before!=null)a.put("before",e.getValue().before.save());undos.add(a);}n.put("undo",undos);return n;}
 public void put(NtTunnel t){NtGeometry.Path path=new NtGeometry.Path(t.plan().points(),t.plan().settings());int expected=path.stations.length;if(t.plan().settings().sides()&&t.plan().left().size()>expected)for(int i=0;i<path.stations.length-1;i++)expected+=Math.max(2,(int)Math.ceil((path.stations[i+1]-path.stations[i])/.75))+1;if(t.plan().left().size()!=expected||t.plan().right().size()!=expected)throw new IllegalArgumentException("Saved support/station count mismatch");List<NtGeometry.Triangle> triangles=NtGeometry.triangles(NtGeometry.panels(path,t.plan()));remove(t.id());tunnels.put(t.id(),t);counts.put(t.id(),triangles.size());bounds.put(t.id(),NtGeometry.boundsOf(t.plan().points()).inflate(t.plan().settings().width()+1,t.plan().settings().height()+24,t.plan().settings().width()+1));for(var tri:triangles){Face face=new Face(t.id(),tri,tri.bounds());forCells(face.bounds,k->cells.computeIfAbsent(k,x->new ArrayList<>()).add(face));}setDirty();}
 public NtTunnel remove(UUID id){NtTunnel old=tunnels.remove(id);if(old!=null){counts.remove(id);bounds.remove(id);var it=cells.entrySet().iterator();while(it.hasNext()){var e=it.next();e.getValue().removeIf(f->f.tunnel.equals(id));if(e.getValue().isEmpty())it.remove();}setDirty();}return old;}
 public Hit hit(AABB box,Vec3 movement){if(cells.isEmpty())return null;AABB swept=box.expandTowards(movement).inflate(.02);Set<Face> seen=Collections.newSetFromMap(new IdentityHashMap<>());List<Face> possible=new ArrayList<>();long cellCount=(long)(((int)Math.floor(swept.maxX)>>4)-((int)Math.floor(swept.minX)>>4)+1)*(((int)Math.floor(swept.maxY)>>4)-((int)Math.floor(swept.minY)>>4)+1)*(((int)Math.floor(swept.maxZ)>>4)-((int)Math.floor(swept.minZ)>>4)+1);if(cellCount>8192){for(var found:cells.values())for(Face f:found)if(seen.add(f)&&swept.intersects(f.bounds))possible.add(f);}else forCells(swept,k->{var found=cells.get(k);if(found!=null)for(Face f:found)if(seen.add(f)&&swept.intersects(f.bounds))possible.add(f);});Hit best=null;for(Face f:possible){double time=NtGeometry.sweep(box,movement,f.triangle);if(Double.isFinite(time)&&(best==null||time<best.time))best=new Hit(f,time);}return best;}
 public boolean overlaps(UUID except,NtGeometry.Plan plan){var path=new NtGeometry.Path(plan.points(),plan.settings());for(var q:NtGeometry.panels(path,plan)){AABB b=q.bounds();final boolean[] found={false};forCells(b,k->{var list=cells.get(k);if(list==null)return;for(Face f:list)if(!f.tunnel.equals(except)&&b.intersects(f.bounds)&&(Double.isFinite(NtGeometry.sweep(b,Vec3.ZERO,f.triangle)))){found[0]=true;break;}});if(found[0])return true;}return false;}
 public AABB bounds(UUID id){return bounds.get(id);}
 public int faceCount(){return counts.values().stream().mapToInt(Integer::intValue).sum();}
 private static void forCells(AABB b,java.util.function.LongConsumer use){int x0=(int)Math.floor(b.minX)>>4,x1=(int)Math.floor(b.maxX)>>4,y0=(int)Math.floor(b.minY)>>4,y1=(int)Math.floor(b.maxY)>>4,z0=(int)Math.floor(b.minZ)>>4,z1=(int)Math.floor(b.maxZ)>>4;if((long)(x1-x0+1)*(y1-y0+1)*(z1-z0+1)>8192)throw new IllegalArgumentException("Movement/query exceeds NT-01 spatial budget");for(int x=x0;x<=x1;x++)for(int y=y0;y<=y1;y++)for(int z=z0;z<=z1;z++)use.accept(SectionPos.asLong(x,y,z));}
}
